/// How one export target ended.
public enum PenExportFileStatus: Hashable, Sendable {
    /// The target already held exactly the generated bytes.
    case unchanged

    /// The target now holds the generated bytes.
    case published

    /// The target was left as it was, with a reason.
    case failed(reason: String)
}

/// One export target's outcome.
public struct PenExportArtifact: Hashable, Sendable {
    /// The format of the target file.
    public let format: PenExportFormat

    /// The path of the target file.
    public let path: String

    /// The size of the generated file in bytes.
    public let byteCount: Int

    /// How the target ended.
    public let status: PenExportFileStatus

    public init(
        format: PenExportFormat,
        path: String,
        byteCount: Int,
        status: PenExportFileStatus
    ) {
        self.format = format
        self.path = path
        self.byteCount = byteCount
        self.status = status
    }

    /// Whether the target file was written by this publication.
    public var didPublish: Bool { status == .published }

    /// The reason the target failed, when it did.
    public var failureReason: String? {
        if case .failed(let reason) = status { return reason }
        return nil
    }
}

/// The per-file result of one publication.
///
/// A report always names every requested target, so the app can say which files
/// were written and which failed instead of reporting one success or failure for
/// the whole set.
public struct PenExportReport: Hashable, Sendable {
    /// One entry per requested target, in request order.
    public let artifacts: [PenExportArtifact]

    public init(artifacts: [PenExportArtifact]) {
        self.artifacts = artifacts
    }

    /// Whether every requested target succeeded.
    ///
    /// An unchanged target counts as a success: its content already matched the
    /// generated bytes.
    public var succeeded: Bool {
        artifacts.allSatisfy { $0.failureReason == nil }
    }

    /// The targets this publication wrote.
    public var published: [PenExportArtifact] {
        artifacts.filter(\.didPublish)
    }

    /// The targets that failed.
    public var failed: [PenExportArtifact] {
        artifacts.filter { $0.failureReason != nil }
    }

    /// The targets whose bytes already matched.
    public var unchanged: [PenExportArtifact] {
        artifacts.filter { $0.status == .unchanged }
    }

    /// The failure reasons, in request order.
    public var failureMessages: [String] {
        artifacts.compactMap(\.failureReason)
    }

    /// Whether no target was requested.
    public var isEmpty: Bool { artifacts.isEmpty }
}
